//! The text forms of a set of variables: the Env file, and the shell exports `procly env` prints.

use std::fmt::Write as _;

/// The first line of the Env file, which tells a reader not to edit what Procly regenerates.
const HEADER: &str =
    "# Generated by procly, do not edit. The Derived variables it injects into the Services of this Worktree.";

/// The Env file: the header, then one `NAME=value` line per variable, quoted only where a dotenv parser needs it.
pub(crate) fn env_file(variables: &[(String, String)]) -> String {
    let mut text = format!("{HEADER}\n");
    for (name, value) in variables {
        let _ = writeln!(text, "{name}={}", dotenv_value(value));
    }
    text
}

/// Whether `text` is an Env file as Procly wrote it, which a file that lost its header is not.
pub(crate) fn is_generated(text: &str) -> bool {
    text.lines().next() == Some(HEADER)
}

/// A value as dotenv parsers read it back unchanged: bare when it holds nothing they treat specially, otherwise in
/// double quotes with `\`, `"`, `$` and the line break escaped. The `$` is escaped because the parsers that expand
/// variables, such as the ones of Next.js and `dotenv-cli`, would expand it even between double quotes.
fn dotenv_value(value: &str) -> String {
    let bare = |c: char| c.is_ascii_alphanumeric() || "_@%+=:,./-".contains(c);
    if value.chars().all(bare) {
        return value.to_owned();
    }
    let mut quoted = String::with_capacity(value.len() + 2);
    quoted.push('"');
    for c in value.chars() {
        match c {
            '\\' => quoted.push_str("\\\\"),
            '"' => quoted.push_str("\\\""),
            '$' => quoted.push_str("\\$"),
            '\n' => quoted.push_str("\\n"),
            '\r' => quoted.push_str("\\r"),
            c => quoted.push(c),
        }
    }
    quoted.push('"');
    quoted
}

/// One `export NAME='value'` line per variable, for a shell to `eval`. Single quotes keep every character literal,
/// a quote in the value closes the string, is escaped, and opens it again.
pub(crate) fn exports(variables: &[(String, String)]) -> String {
    let mut text = String::new();
    for (name, value) in variables {
        let _ = writeln!(text, "export {name}='{}'", value.replace('\'', r"'\''"));
    }
    text
}

#[cfg(test)]
mod tests {
    use super::*;

    fn variables(pairs: &[(&str, &str)]) -> Vec<(String, String)> {
        pairs
            .iter()
            .map(|(name, value)| ((*name).to_owned(), (*value).to_owned()))
            .collect()
    }

    #[test]
    fn the_env_file_holds_a_header_then_one_line_per_variable() {
        assert_eq!(
            env_file(&variables(&[
                ("API_URL", "http://localhost:24000/v1"),
                ("COOKIE", "web_app_other")
            ])),
            format!("{HEADER}\nAPI_URL=http://localhost:24000/v1\nCOOKIE=web_app_other\n")
        );
        assert_eq!(env_file(&[]), format!("{HEADER}\n"));
    }

    #[test]
    fn the_env_file_quotes_what_a_dotenv_parser_would_misread() {
        assert_eq!(
            env_file(&variables(&[
                ("A", "two words"),
                ("B", "say \"hi\" \\ now"),
                ("C", "line\nbreak"),
                ("D", ""),
                ("E", "a#b"),
                ("F", "$HOME")
            ])),
            format!(
                "{HEADER}\nA=\"two words\"\nB=\"say \\\"hi\\\" \\\\ now\"\nC=\"line\\nbreak\"\nD=\nE=\"a#b\"\nF=\"\\$HOME\"\n"
            )
        );
    }

    #[test]
    fn the_exports_single_quote_every_value() {
        assert_eq!(
            exports(&variables(&[("PORT", "24000"), ("GREETING", "it's $HOME `x`")])),
            "export PORT='24000'\nexport GREETING='it'\\''s $HOME `x`'\n"
        );
        assert_eq!(exports(&[]), "");
    }

    #[test]
    fn an_env_file_is_told_by_its_header() {
        assert!(is_generated(&env_file(&variables(&[("A", "1")]))));
        assert!(is_generated(&env_file(&[])));
        assert!(!is_generated("A=1\n"));
        assert!(!is_generated(""));
    }
}
